#include <cstdio>
#include <algorithm>
#include <cmath>
using namespace std;

int n, m, mod;
int g[505], sg[505];
int f[505][505], sf[505][505];

namespace calc {
    int C[505][505];

    int add(int a, int b) {
        return (a + b) >= mod ? a + b - mod : a + b;
    }

    int sub(int a, int b) {
        return (a < b) ? a - b + mod : a - b;
    }

    void compute_C() {
        C[0][0] = 1;
        for (int i = 1; i <= n; ++i) {
            C[i][0] = 1;
            for (int j = 1; j <= i; ++j) {
                C[i][j] = add(C[i - 1][j], C[i - 1][j - 1]);
            }
        }
    }
}

using namespace calc;

int sum_series(int x) {
    return (long long)x * (x + 1) / 2 % mod;
}

int main() {
    scanf("%d %d %d", &n, &m, &mod);
    compute_C();

    g[0] = 1;
    for (int i = 1; i <= m; ++i) {
        for (int j = 1; j <= i; ++j) {
            int tmp = (long long)g[j - 1] * g[i - j] % mod * C[i - 1][j - 1] % mod;
            g[i] = add(g[i], (long long)tmp * (i + 1));
            sg[i] = add(sg[i], (long long)sg[j - 1] * g[i - j] % mod * C[i - 1][j - 1] % mod * (i + 1));
            sg[i] = add(sg[i], (long long)sg[i - j] * g[j - 1] % mod * C[i - 1][j - 1] % mod * (i + 1));
            sg[i] = add(sg[i], (long long)tmp * (sum_series(i - j) + sum_series(j - 1)));
        }
    }

    for (int i = 0; i <= n; ++i) f[i][0] = 1;

    for (int i = 1; i <= n; ++i) {
        if (i <= m) {
            f[i][i] = g[i];
            sf[i][i] = sg[i];
        }
        for (int j = 1; j <= min(i - 1, m); ++j) {
            for (int t = i; t >= 1; --t) {
                if (i - t > j) break;
                int tmp = (long long)g[i - t] * C[j][i - t] % mod;
                f[i][j] = add(f[i][j], (long long)f[t - 1][j - i + t] * tmp);
                sf[i][j] = add(sf[i][j], (long long)sf[t - 1][j - i + t] * tmp);
                sf[i][j] = add(sf[i][j], (long long)f[t - 1][j - i + t] * sg[i - t] % mod * C[j][i - t]);
            }
        }
    }

    printf("%d\n", sf[n][m]);
    return 0;
}
